 private final ExecutorService worker=Executors.newSingleThreadExecutor();private EditText query;private TextView status;private Spinner choice,pack;private int packGeneration;private boolean packLoading;private String packNotice="";private GridLayout grid;private LinearLayout tabs;private String category="全部",area="全部地区",year="全部年份";private final List<Result> results=new ArrayList<>();private List<TvBoxConfig.Site> sources=new ArrayList<>();private volatile int generation;private Future<?> searchJob;private int page=1,displayLimit=24;private boolean ready,typeMode;
 private static final class Result{final TvBoxConfig.Site site;final List<VodApi.Movie> movies;Result(TvBoxConfig.Site s,List<VodApi.Movie> m){site=s;movies=m;}}
 @Override public void onCreate(Bundle state){super.onCreate(state);if(state!=null){category=state.getString("category","全部");page=state.getInt("page",1);typeMode=state.getBoolean("typeMode",false);}LinearLayout root=TvUi.root(this);LinearLayout top=TvUi.row(this);TextView logo=TvUi.title(this,"✦  星幕",25);logo.setTextColor(TvUi.ACCENT);top.addView(logo);top.addView(TvUi.text(this,"  影视",18,TvUi.INK),new LinearLayout.LayoutParams(0,-2,1));Button mode=TvUi.button(this,"切换模式"),settings=TvUi.button(this,"设置");Button downloads=TvUi.button(this,"下载");downloads.setOnClickListener(v->startActivity(new Intent(this,DownloadsActivity.class)));if(getResources().getConfiguration().screenWidthDp<600){mode.setText("模式");for(Button button:new Button[]{downloads,mode,settings}){button.setMinWidth(0);button.setMinimumWidth(0);button.setTextSize(12);button.setPadding(TvUi.dp(this,8),0,TvUi.dp(this,8),0);}}top.addView(downloads);top.addView(mode);top.addView(settings);mode.setOnClickListener(v->finish());settings.setOnClickListener(v->startActivity(new Intent(this,SettingsActivity.class)));root.addView(top);TvUi.gap(this,root,14);
 HorizontalScrollView navigation=new HorizontalScrollView(this);navigation.setHorizontalScrollBarEnabled(false);tabs=TvUi.row(this);navigation.addView(tabs);root.addView(navigation);renderTabs();TvUi.gap(this,root,12);
 LinearLayout searchRow=TvUi.row(this);query=new EditText(this);query.setSingleLine(true);query.setHint("输入片名或类型，如动作 / 喜剧 / 科幻");TvUi.styleSearch(this,query);if(state!=null)query.setText(state.getString("query",""));searchRow.addView(query,new LinearLayout.LayoutParams(0,TvUi.dp(this,46),1));Button search=TvUi.button(this,"搜片名"),genre=TvUi.button(this,"搜类型");searchRow.addView(search);searchRow.addView(genre);search.setOnClickListener(v->{typeMode=false;page=1;search();});genre.setOnClickListener(v->{if(query.getText().toString().trim().isEmpty()){new AlertDialog.Builder(this).setTitle("选择影片类型").setItems(new String[]{"动作","喜剧","悬疑","爱情","科幻","恐怖","战争","纪录","动画"},(d,n)->{query.setText(new String[]{"动作","喜剧","悬疑","爱情","科幻","恐怖","战争","纪录","动画"}[n]);typeMode=true;page=1;search();}).show();}else{typeMode=true;page=1;search();}});query.setOnEditorActionListener((v,id,event)->{page=1;search();return true;});root.addView(searchRow);TvUi.gap(this,root,8);
 try{sources=new SourceRepository(this).load().sites;}catch(Exception ignored){}ArrayList<String> names=new ArrayList<>();names.add("聚合源 · 全部");for(TvBoxConfig.Site site:sources)names.add(site.name);LinearLayout packs=TvUi.row(this);pack=spinner(Arrays.asList(FilmPackRepository.NAMES));packs.addView(pack,new LinearLayout.LayoutParams(0,TvUi.dp(this,44),1));Button reload=TvUi.button(this,"更新源包");packs.addView(reload);reload.setOnClickListener(v->loadPack(true));root.addView(packs);pack.setSelection(Math.min(getSharedPreferences("settings",0).getInt("film_pack",0),FilmPackRepository.NAMES.length-1));pack.setOnItemSelectedListener(selected(v->{if(ready)loadPack(false);}));HorizontalScrollView filters=new HorizontalScrollView(this);LinearLayout filterRow=TvUi.row(this);filters.addView(filterRow);root.addView(filters);choice=spinner(names);filterRow.addView(choice,new LinearLayout.LayoutParams(TvUi.dp(this,220),TvUi.dp(this,44)));Spinner regions=spinner(Arrays.asList("全部地区","中国大陆","中国香港","中国台湾","日本","韩国","美国","其他地区")),years=spinner(Arrays.asList("全部年份","2026","2025","2024","2023","2022","2021","2020","2019及以前"));filterRow.addView(regions,new LinearLayout.LayoutParams(TvUi.dp(this,150),TvUi.dp(this,44)));filterRow.addView(years,new LinearLayout.LayoutParams(TvUi.dp(this,150),TvUi.dp(this,44)));regions.setOnItemSelectedListener(selected(v->{area=v;if(ready)renderResults();}));years.setOnItemSelectedListener(selected(v->{year=v;if(ready)renderResults();}));choice.setSelection(Math.min(getSharedPreferences("settings",0).getInt("film_source",0),sources.size()));choice.setOnItemSelectedListener(selected(v->{if(ready&&!packLoading){getSharedPreferences("settings",0).edit().putInt("film_source",choice.getSelectedItemPosition()).apply();page=1;search();}}));
 TvUi.gap(this,root,10);LinearLayout title=TvUi.row(this);title.addView(TvUi.title(this,"片库 · 为你发现",20),new LinearLayout.LayoutParams(0,-2,1));Button saved=TvUi.button(this,"收藏 / 历史");saved.setOnClickListener(v->new AlertDialog.Builder(this).setItems(new String[]{"我的收藏","最近观看","已保存影片"},(d,n)->startActivity(new Intent(this,LibraryActivity.class).putExtra("section",n==0?"favourites":n==1?"history":"films"))).show());title.addView(saved);root.addView(title);status=TvUi.text(this,"正在载入片库…",13,TvUi.MUTED);root.addView(status);TvUi.gap(this,root,8);ScrollView scroll=new ScrollView(this);grid=new GridLayout(this);grid.setClipChildren(false);scroll.addView(grid);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));LinearLayout pager=TvUi.row(this);Button prev=TvUi.button(this,"上一页"),next=TvUi.button(this,"下一页");pager.addView(prev,new LinearLayout.LayoutParams(0,-2,1));pager.addView(next,new LinearLayout.LayoutParams(0,-2,1));prev.setOnClickListener(v->{if(page>1){page--;search();}});next.setOnClickListener(v->{page++;search();});root.addView(pager);ready=true;if(pack.getSelectedItemPosition()>0)loadPack(false);else search();}
 private interface Selection{void set(String value);}
 private AdapterView.OnItemSelectedListener selected(Selection callback){return new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int n,long id){callback.set(String.valueOf(p.getItemAtPosition(n)));}};}
 private Spinner spinner(List<String> names){Spinner spinner=new Spinner(this);spinner.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,names){public View getView(int pos,View reused,ViewGroup parent){TextView t=TvUi.text(FilmSearchActivity.this,getItem(pos),13,TvUi.INK);t.setPadding(10,8,10,8);t.setSingleLine(true);return t;}public View getDropDownView(int pos,View reused,ViewGroup parent){TextView t=TvUi.text(FilmSearchActivity.this,getItem(pos),15,TvUi.INK);t.setPadding(16,14,16,14);t.setBackgroundColor(TvUi.BG);return t;}});return spinner;}
 private void renderTabs(){tabs.removeAllViews();for(String value:FilmCategory.OPTIONS){Button tab=TvUi.button(this,value.equals("全部")?"精选":value);if(value.equals(category)){tab.setTextColor(TvUi.ACCENT);tab.setBackground(TvUi.box(0xff20392e,TvUi.ACCENT));}LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,-2);p.rightMargin=TvUi.dp(this,8);tabs.addView(tab,p);tab.setOnClickListener(v->{category=value;page=1;renderTabs();if(ready)search();});}}
 private void search(){if(!ready||packLoading)return;boolean byType=typeMode;String word=query.getText().toString().trim(),browseCategory=category;int requestedPage=page;int token=++generation;if(searchJob!=null)searchJob.cancel(true);results.clear();displayLimit=24;grid.removeAllViews();if(sources.isEmpty()){status.setText(packNotice.isEmpty()?"暂无兼容影视源，请在设置中导入配置。":packNotice);return;}int selected=choice.getSelectedItemPosition();List<TvBoxConfig.Site> targets=selected<=0?new ArrayList<>(sources):Collections.singletonList(sources.get(selected-1));status.setText("正在加载 "+(byType&&!word.isEmpty()?"类型 · "+word:category.equals("全部")?"精选":category)+" · 第 "+page+" 页");((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(query.getWindowToken(),0);
 searchJob=worker.submit(()->{if(token!=generation)return;ExecutorService requests=Executors.newFixedThreadPool(3);CompletionService<Result> completed=new ExecutorCompletionService<>(requests);for(TvBoxConfig.Site site:targets)completed.submit(()->new Result(site,word.isEmpty()?VodApi.browse(site.api,browseCategory,requestedPage):byType?VodApi.browseGenre(site.api,word,requestedPage):VodApi.parse(PublicHttp.get(VodApi.query(site.api,"wd",word)+"&pg="+requestedPage))));int failures=0,finished=0;long deadline=SystemClock.elapsedRealtime()+18000;try{while(finished<targets.size()&&token==generation){long remaining=deadline-SystemClock.elapsedRealtime();if(remaining<=0)break;Future<Result> next=completed.poll(remaining,TimeUnit.MILLISECONDS);if(next==null)break;finished++;try{Result result=next.get();for(VodApi.Movie movie:result.movies)VodCache.put(result.site.api,movie);int progress=finished;runOnUiThread(()->{if(isDestroyed()||token!=generation)return;results.add(result);int count=renderResults();status.setText(count+" 部 · 第 "+requestedPage+" 页 · 已完成 "+progress+"/"+targets.size()+" 个源");});}catch(ExecutionException|CancellationException e){failures++;}}}catch(InterruptedException e){Thread.currentThread().interrupt();}finally{requests.shutdownNow();}int failed=failures+targets.size()-finished;runOnUiThread(()->{if(isDestroyed()||token!=generation)return;int count=renderResults();status.setText(count+" 部 · 第 "+requestedPage+" 页"+(failed>0?" · "+failed+" 个源未响应":"")+(packNotice.isEmpty()?"":" · "+packNotice));if(count==0){TextView empty=TvUi.text(this,"没有可显示内容。可更换影视源、清空筛选或搜索片名。",17,TvUi.MUTED);GridLayout.LayoutParams p=new GridLayout.LayoutParams(GridLayout.spec(0),GridLayout.spec(0,grid.getColumnCount()));p.width=-1;grid.addView(empty,p);}});});}
 private boolean match(VodApi.Movie movie){if(!FilmCategory.matches(movie.category,category))return false;if(!area.equals("全部地区")){String region=movie.area;if(area.equals("中国大陆")){if(!(region.contains("大陆")||region.equals("中国")))return false;}else if(area.equals("其他地区")){if(region.isEmpty()||region.matches(".*(大陆|中国|香港|台湾|日本|韩国|美国).*"))return false;}else if(!region.contains(area.replace("中国","")))return false;}if(!year.equals("全部年份")){if(year.equals("2019及以前")){try{if(Integer.parseInt(movie.year)>2019)return false;}catch(NumberFormatException e){return false;}}else if(!year.equals(movie.year))return false;}return true;}
 private int renderResults(){grid.removeAllViews();int width=getResources().getConfiguration().screenWidthDp,columns=width>=1100?6:width>=840?5:width>=600?4:2;grid.setColumnCount(columns);int count=0;Set<String> seen=new HashSet<>();for(Result result:results)for(VodApi.Movie movie:result.movies){if(!match(movie)||!seen.add(result.site.api+"\n"+movie.id))continue;int n=count++;if(n>=displayLimit)continue;MovieCard card=new MovieCard(this,movie,result.site.name);GridLayout.LayoutParams p=new GridLayout.LayoutParams(GridLayout.spec(n/columns),GridLayout.spec(n%columns,1,1f));p.width=0;p.height=TvUi.dp(this,248);p.bottomMargin=TvUi.dp(this,12);if(n%columns>0)p.leftMargin=TvUi.dp(this,12);grid.addView(card,p);card.setOnClickListener(v->startActivity(new Intent(this,EpisodeActivity.class).putExtra("api",result.site.api).putExtra("source",result.site.name).putExtra("site",result.site.key).putExtra("movie",movie.id).putExtra("title",movie.title)));}if(count>displayLimit){Button more=TvUi.button(this,"显示本页更多内容（"+displayLimit+" / "+count+"）");GridLayout.LayoutParams p=new GridLayout.LayoutParams(GridLayout.spec((displayLimit+columns-1)/columns),GridLayout.spec(0,columns));p.width=-1;grid.addView(more,p);more.setOnClickListener(v->{displayLimit+=24;renderResults();});}return count;}
 private void loadPack(boolean refresh){if(!ready)return;int index=pack.getSelectedItemPosition(),token=++packGeneration;generation++;if(searchJob!=null)searchJob.cancel(true);packLoading=true;results.clear();grid.removeAllViews();status.setText("正在读取源包 · "+FilmPackRepository.NAMES[index]);getSharedPreferences("settings",0).edit().putInt("film_pack",index).apply();worker.execute(()->{try{TvBoxConfig config=new FilmPackRepository(this).load(index,refresh);runOnUiThread(()->{if(isDestroyed()||packGeneration!=token)return;sources=config.sites;packNotice=config.unsupported>0?config.unsupported+" 个插件站点暂不兼容":"";if(sources.isEmpty())packNotice="此源包没有标准影视接口"+(config.unsupported>0?"，"+config.unsupported+" 个站点依赖插件":"");ArrayList<String> names=new ArrayList<>();names.add("包内站点 · 全部");for(TvBoxConfig.Site site:sources)names.add(site.name);choice.setAdapter(spinner(names).getAdapter());choice.setSelection(0);packLoading=false;page=1;search();});}catch(Exception e){runOnUiThread(()->{if(isDestroyed()||packGeneration!=token)return;packLoading=false;sources=new ArrayList<>();choice.setAdapter(spinner(Collections.singletonList("无法读取站点")).getAdapter());status.setText("源包读取失败："+e.getMessage()+"。可更新重试或更换源包。");});}});}
 @Override protected void onResume(){super.onResume();if(!ready||pack==null||pack.getSelectedItemPosition()!=0)return;try{List<TvBoxConfig.Site> updated=new SourceRepository(this).load().sites;StringBuilder old=new StringBuilder(),fresh=new StringBuilder();for(TvBoxConfig.Site site:sources)old.append(site.api).append(site.name);for(TvBoxConfig.Site site:updated)fresh.append(site.api).append(site.name);if(!old.toString().equals(fresh.toString())){sources=updated;ArrayList<String> names=new ArrayList<>();names.add("聚合源 · 全部");for(TvBoxConfig.Site site:sources)names.add(site.name);choice.setAdapter(spinner(names).getAdapter());choice.setSelection(0);page=1;search();}}catch(Exception ignored){}}
 @Override protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putString("query",query.getText().toString());out.putString("category",category);out.putInt("page",page);out.putBoolean("typeMode",typeMode);}
